-- ============================================
-- LUMA — Thème 1 (Restaurant) : scénario MOYEN 3/3 x4 — Un dîner d'anniversaire surprise
-- ============================================


update scenarios set content = '{"characters": {"manager": "le responsable de salle"}, "start_node": "n1", "nodes": {"n1": {"speaker": "manager", "text": "Hi, you mentioned you''re planning a surprise tonight — tell me more.", "text_fr": "Bonjour, vous avez mentionné que vous prépariez une surprise ce soir — dites-m''en plus.", "choices": [{"text": "Yes, it''s my sister''s birthday, she has no idea we''re all coming.", "text_fr": "Oui, c''est l''anniversaire de ma sœur, elle n''a aucune idée qu''on vient tous.", "next": "n2"}, {"text": "It''s a surprise engagement party, actually.", "text_fr": "C''est une fête de fiançailles surprise, en fait.", "next": "n2b"}]}, "n2": {"speaker": "manager", "text": "Wonderful, happy to help! How many guests, and when will she arrive?", "text_fr": "Merveilleux, ravi d''aider ! Combien d''invités, et quand arrive-t-elle ?", "choices": [{"text": "About twelve of us, she''ll arrive around 8pm thinking it''s just us two.", "text_fr": "Environ douze d''entre nous, elle arrivera vers 20h en pensant que c''est juste nous deux.", "next": "n3"}]}, "n2b": {"speaker": "manager", "text": "How exciting! How many people, and what''s the plan for the reveal?", "text_fr": "Quelle excitation ! Combien de personnes, et quel est le plan pour la révélation ?", "choices": [{"text": "About fifteen guests, hiding in a private room until the ring moment.", "text_fr": "Environ quinze invités, cachés dans une salle privée jusqu''au moment de la bague.", "next": "n3b"}]}, "n3": {"speaker": "manager", "text": "Perfect, we have a private room in the back that seats twelve comfortably.", "text_fr": "Parfait, on a une salle privée à l''arrière qui accueille douze personnes confortablement.", "choices": [{"text": "That sounds perfect, could we decorate it beforehand?", "text_fr": "Ça a l''air parfait, on pourrait la décorer avant ?", "next": "n4"}, {"text": "Great — should the guests arrive before or after her?", "text_fr": "Super — les invités devraient arriver avant ou après elle ?", "next": "n4b"}]}, "n3b": {"speaker": "manager", "text": "We can definitely arrange that — I''ll assign a staff member just for your group.", "text_fr": "On peut certainement arranger ça — j''assigne un membre du personnel juste pour votre groupe.", "choices": [{"text": "That would be amazing, thank you.", "text_fr": "Ce serait incroyable, merci.", "next": "n4c"}]}, "n4": {"speaker": "manager", "text": "Of course, come by an hour early and we''ll help set up balloons and a banner.", "text_fr": "Bien sûr, venez une heure en avance et on aidera à installer des ballons et une banderole.", "choices": [{"text": "Perfect, we''ll bring the decorations then.", "text_fr": "Parfait, on apportera les décorations alors.", "next": "n5"}]}, "n4b": {"speaker": "manager", "text": "I''d suggest guests arrive thirty minutes early and hide in the private room.", "text_fr": "Je suggérerais que les invités arrivent trente minutes en avance et se cachent dans la salle privée.", "choices": [{"text": "Good idea, we''ll coordinate that timing.", "text_fr": "Bonne idée, on va coordonner ce timing.", "next": "n5"}]}, "n4c": {"speaker": "manager", "text": "They''ll guide your guests in quietly and keep an eye on the timing for the reveal.", "text_fr": "Ils guideront vos invités discrètement et surveilleront le timing pour la révélation.", "choices": [{"text": "That''s very reassuring, thank you.", "text_fr": "C''est très rassurant, merci.", "next": "n5"}]}, "n5": {"speaker": "manager", "text": "Now, how should we signal when it''s time for the surprise?", "text_fr": "Maintenant, comment on signale que c''est le moment pour la surprise ?", "choices": [{"text": "Could the lights dim slightly as a cue?", "text_fr": "Les lumières pourraient baisser légèrement comme signal ?", "next": "n6"}, {"text": "We''ll just wait for her to sit down, then everyone jumps out.", "text_fr": "On va juste attendre qu''elle s''assoie, puis tout le monde surgit.", "next": "n6b"}]}, "n6": {"speaker": "manager", "text": "We can do that — I''ll have staff dim the lights right on cue.", "text_fr": "On peut faire ça — j''aurai du personnel pour baisser les lumières au bon moment.", "choices": [{"text": "Perfect, that adds a nice dramatic touch.", "text_fr": "Parfait, ça ajoute une belle touche dramatique.", "next": "n7"}]}, "n6b": {"speaker": "manager", "text": "Simple and effective! I''ll make sure the room stays quiet until then.", "text_fr": "Simple et efficace ! Je m''assurerai que la salle reste calme jusque-là.", "choices": [{"text": "Thank you, that''s exactly what we need.", "text_fr": "Merci, c''est exactement ce dont on a besoin.", "next": "n7"}]}, "n7": {"speaker": "manager", "text": "One more thing — would you like a cake brought out after the surprise?", "text_fr": "Une dernière chose — vous voulez qu''un gâteau soit apporté après la surprise ?", "choices": [{"text": "Yes, we already ordered one, could you keep it chilled until then?", "text_fr": "Oui, on en a déjà commandé un, vous pourriez le garder au frais jusque-là ?", "next": "n8"}, {"text": "We hadn''t thought of that — could you provide one?", "text_fr": "On n''y avait pas pensé — vous pourriez en fournir un ?", "next": "n8b"}]}, "n8": {"speaker": "manager", "text": "Absolutely, we''ll keep it safely in our fridge and bring it out on your signal.", "text_fr": "Absolument, on va le garder en sécurité au frigo et l''apporter à votre signal.", "choices": [{"text": "Perfect, thank you for all this help.", "text_fr": "Parfait, merci pour toute cette aide.", "next": "n9"}]}, "n8b": {"speaker": "manager", "text": "Of course, our chef makes a lovely chocolate cake — I''ll have it ready.", "text_fr": "Bien sûr, notre chef fait un délicieux gâteau au chocolat — je vais le préparer.", "choices": [{"text": "That sounds wonderful, thank you.", "text_fr": "Ça a l''air merveilleux, merci.", "next": "n9"}]}, "n9": {"speaker": "manager", "text": "Everything''s set. This is going to be a beautiful surprise!", "text_fr": "Tout est prêt. Ça va être une magnifique surprise !", "choices": [{"text": "Thank you so much for your help with all of this.", "text_fr": "Merci beaucoup pour votre aide avec tout ça.", "next": "end_perfect"}]}, "end_perfect": {"speaker": "manager", "text": "It''s our pleasure — we love making these moments special. See you tonight!", "text_fr": "C''est un plaisir — on adore rendre ces moments spéciaux. À ce soir !", "end": true, "ending_label": "Surprise parfaitement orchestrée 🎉"}}}'::jsonb, is_playable = true
where title = 'Un dîner d''''anniversaire surprise'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
